package main

import (
	"fmt"
	"sync"
)

var cache sync.Map // concurrency-safe; values stored as any

func getConn(key string) int {
	// LoadOrStore atomically returns an existing value or stores a new one.
	actual, _ := cache.LoadOrStore(key, len(key)) // len(key) stands in for an expensive create
	return actual.(int)                            // assert back to the concrete type
}

func main() {
	fmt.Println(getConn("alpha"), getConn("alpha")) // same value, created once
}

