package solution

import "sync"

type Counter struct {
	mu sync.Mutex
	n  int
}

func (c *Counter) Inc() {
	c.mu.Lock()
	c.n++
	c.mu.Unlock()
}

func (c *Counter) Value() int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.n
}

var (
	once     sync.Once
	instance *Counter
)

// Get lazily creates the shared Counter exactly once and returns it.
func Get() *Counter {
	once.Do(func() {
		instance = &Counter{} // runs on the first call only
	})
	return instance // once.Do publishes the write safely
}

