package solution

import (
	"sync"
	"testing"
)

func TestGetIsSingleton(t *testing.T) {
	if Get() != Get() {
		t.Fatal("Get returned different instances")
	}
}

func TestConcurrentIncrements(t *testing.T) {
	const goroutines, perG = 50, 100
	var wg sync.WaitGroup
	for i := 0; i < goroutines; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			c := Get() // every goroutine gets the same instance
			for j := 0; j < perG; j++ {
				c.Inc()
			}
		}()
	}
	wg.Wait()
	if got, want := Get().Value(), goroutines*perG; got != want {
		t.Errorf("Value()=%d want %d", got, want)
	}
}

