import "sync"

type LazyMap[K comparable, V any] struct {
	m sync.Map // K -> *entry[V]
}

type entry[V any] struct {
	once sync.Once
	val  V
}

// Get returns the value for key, invoking builder exactly once per key
// even when many goroutines call Get(key, ...) concurrently.
func (l *LazyMap[K, V]) Get(key K, builder func() V) V {
	// LoadOrStore atomically installs one shared entry per key.
	actual, _ := l.m.LoadOrStore(key, &entry[V]{})
	e := actual.(*entry[V])
	// Only the first goroutine for this key runs builder; the rest wait.
	e.once.Do(func() {
		e.val = builder()
	})
	return e.val // published safely by once.Do
}

import "sync"

type Once[T any] struct {
	once sync.Once
	val  T
}

// Do runs f exactly once across all goroutines and caches the result.
func (o *Once[T]) Do(f func() T) T {
	o.once.Do(func() {
		o.val = f() // computed on the first call only
	})
	return o.val // once.Do publishes o.val to all callers
}
